int solid_profile(vector p[]; vector direction; float depth; string material; string name; vector color)
{
    int prim=addprim(0,"poly");
    int reverse=dot(cross(p[1]-p[0],p[2]-p[0]),direction)>0.;
    for(int i=0;i<len(p);i++)
    {
        int index=reverse ? len(p)-1-i : i;
        int pt=addpoint(0,p[index]);addvertex(0,prim,pt);
        setpointattrib(0,"extrude_direction",pt,direction,"set");
    }
    setprimattrib(0,"extrude_distance",prim,depth,"set");
    setprimattrib(0,"material_family",prim,material,"set");
    setprimattrib(0,"name",prim,name,"set");
    setprimattrib(0,"Cd",prim,color,"set");
    return prim;
}

int count=nprimitives(0),hipped=chs("../roof_shape")=="hipped";
float board=ch("../board_width"),drop=ch("../board_height"),tile=ch("../tile_size");
for(int src=0;src<count;src++)
{
    float w=prim(0,"width",src),d=prim(0,"depth",src),top=prim(0,"top_y",src);
    float e=prim(0,"eave",src),h=prim(0,"roof_h",src),curve=prim(0,"curve",src);
    float angle=prim(0,"rot_y",src);vector center=prim(0,"role_center",src);center.y=0.;
    matrix3 rot=ident();rotate(rot,radians(angle),set(0.,1.,0.));
    float hw=w*.5+e,hd=d*.5+e;
    if(!int(prim(0,"is_round",src)))
    {
        int steps=max(5,int(ceil(hw/max(tile,.16))));
        // Four planar curved gable-edge ribbons, extruded together in one SOP.
        if(!hipped)for(int end=0;end<2;end++)for(int side=0;side<2;side++)
        {
            float z=end==0 ? -hd-board*.22 : hd-board*.78;
            float sign=side==0 ? -1. : 1.;vector p[];
            for(int k=0;k<=steps;k++)
            {
                float q=float(k)/steps,x=sign*hw*q,y=top+h*(1.-q)+curve*pow(q,4.)+.015;
                append(p,set(x,y,z)*rot+center);
            }
            for(int k=steps;k>=0;k--)
            {
                float q=float(k)/steps,x=sign*hw*q,y=top+h*(1.-q)+curve*pow(q,4.)+.015-drop;
                append(p,set(x,y,z)*rot+center);
            }
            solid_profile(p,set(0.,0.,1.)*rot,board,"wood","roof_bargeboard",set(.205,.105,.045));
        }
        // Two straight eave boards share the same extrusion stream.
        for(int side=0;side<2;side++)
        {
            float x=side==0 ? -hw-board*.22 : hw-board*.78,y=top+curve+.015;
            vector p[]=array(set(x,y,-hd),set(x,y,hd),set(x,y-drop,hd),set(x,y-drop,-hd));
            for(int k=0;k<len(p);k++)p[k]=p[k]*rot+center;
            solid_profile(p,set(1.,0.,0.)*rot,board,"wood","roof_eave_board",set(.205,.105,.045));
        }
        if(hipped)for(int end=0;end<2;end++)
        {
            float z=end==0 ? -hd-board*.22 : hd-board*.78,y=top+curve+.015;
            vector p[]=array(set(-hw,y,z),set(hw,y,z),set(hw,y-drop,z),set(-hw,y-drop,z));
            for(int k=0;k<len(p);k++)p[k]=p[k]*rot+center;
            solid_profile(p,set(0.,0.,1.)*rot,board,"wood","roof_eave_board",set(.205,.105,.045));
        }
    }
    else
    {
        // A thin annulus supports the cone eave. Native extrusion supplies depth.
        int segments=48;float y=top+curve-drop;
        for(int k=0;k<segments;k++)
        {
            float a=2.*M_PI*k/segments,b=2.*M_PI*(k+1)/segments;
            vector p[]=array(set(hw*cos(a),y,hw*sin(a)),set(hw*cos(b),y,hw*sin(b)),
                             set((hw-board)*cos(b),y,(hw-board)*sin(b)),set((hw-board)*cos(a),y,(hw-board)*sin(a)));
            for(int j=0;j<len(p);j++)p[j]+=center;
            solid_profile(p,set(0.,1.,0.),drop,"wood","cone_eave_ring",set(.205,.105,.045));
        }
    }
}
for(int p=count-1;p>=0;p--)removeprim(0,p,1);

int solid_profile(vector p[]; vector direction; float depth; string material; string name; vector color)
{
    int prim=addprim(0,"poly");
    int reverse=dot(cross(p[1]-p[0],p[2]-p[0]),direction)>0.;
    for(int i=0;i<len(p);i++)
    {
        int index=reverse ? len(p)-1-i : i;
        int pt=addpoint(0,p[index]);addvertex(0,prim,pt);
        setpointattrib(0,"extrude_direction",pt,direction,"set");
    }
    setprimattrib(0,"extrude_distance",prim,depth,"set");
    setprimattrib(0,"material_family",prim,material,"set");
    setprimattrib(0,"name",prim,name,"set");
    setprimattrib(0,"Cd",prim,color,"set");
    return prim;
}

vector p[];int steps=12;float outer=.18,inner=.12;
for(int k=0;k<=steps;k++){float a=M_PI*k/steps;append(p,set(outer*cos(a),outer*sin(a),-.5));}
for(int k=steps;k>=0;k--){float a=M_PI*k/steps;append(p,set(inner*cos(a),inner*sin(a),-.5));}
solid_profile(p,set(0.,0.,1.),1.,"tile","roof_ridge_cap",set(.76,.24,.105));

int count=nprimitives(0);float spacing=max(.16,ch("../tile_size"));
for(int src=0;src<count;src++)
{
    if(int(prim(0,"is_round",src)))continue;
    float w=prim(0,"width",src),d=prim(0,"depth",src),e=prim(0,"eave",src),top=prim(0,"top_y",src),h=prim(0,"roof_h",src);
    float angle=prim(0,"rot_y",src);vector center=prim(0,"role_center",src);center.y=0.;
    float span=chs("../roof_shape")=="hipped" ? max(.035,d-w) : d+2.*e;
    int n=max(1,int(ceil(span/spacing)));float step=span/n;
    matrix3 rot=ident();rotate(rot,radians(angle),set(0.,1.,0.));
    matrix3 frame=ident();scale(frame,set(1.,1.,step*.97));rotate(frame,radians(angle),set(0.,1.,0.));
    for(int k=0;k<n;k++)
    {
        vector local=set(0.,top+h+.055,-span*.5+(k+.5)*step);
        int pt=addpoint(0,local*rot+center);
        setpointattrib(0,"transform",pt,frame,"set");
        setpointattrib(0,"role_id",pt,int(prim(0,"role_id",src)),"set");
    }
}
for(int p=count-1;p>=0;p--)removeprim(0,p,1);

int old=nprimitives(0),count=clamp(chi("../chimney_count"),0,3);
for(int src=0;src<old;src++)
{
    if(string(prim(0,"role",src))!="main")continue;
    float w=prim(0,"width",src),d=prim(0,"depth",src),top=prim(0,"top_y",src),h=prim(0,"roof_h",src);
    float e=prim(0,"eave",src),curve=prim(0,"curve",src),angle=prim(0,"rot_y",src);
    vector center=prim(0,"role_center",src);center.y=0.;
    matrix3 rot=ident();rotate(rot,radians(angle),set(0.,1.,0.));
    for(int k=0;k<count;k++)
    {
        float x=-w*.23,z=(k-(count-1)*.5)*1.65;
        float radius=int(prim(0,"is_round",src)) ? length(set(x,0.,z)) : abs(x);
        float q=radius/max(w*.5+e,1e-5);
        if(chs("../roof_shape")=="hipped" && !int(prim(0,"is_round",src)))
        {
            float tipz=max(.0175,(d-w)*.5);
            q=max(max(0.,(abs(x)-.0175)/max(w*.5+e-.0175,1e-5)),
                  max(0.,(abs(z)-tipz)/max(d*.5+e-tipz,1e-5)));
        }
        float y=top+h*(1.-q)+curve*pow(q,4.)+.7;
        int pt=addpoint(0,set(x,y,z)*rot+center);
        setpointattrib(0,"transform",pt,rot,"set");
        setpointattrib(0,"chimney_id",pt,k,"set");
        setpointattrib(0,"role_id",pt,int(prim(0,"role_id",src)),"set");
    }
    break;
}
for(int p=old-1;p>=0;p--)removeprim(0,p,1);

vector worldpos(vector p; vector center; float angle)
{
    float c=cos(radians(angle)),s=sin(radians(angle));
    return set(center.x+c*p.x+s*p.z,p.y,center.z-s*p.x+c*p.z);
}

void rectprofile(float xa;float xb;float za;float zb;float y;float depth;
                 vector center;float angle;string part;string role;int rid;int level)
{
    if(xb-xa<.005 || zb-za<.005) return;
    // The source profile faces -Y. Its back cap becomes the walking surface.
    vector p[]=array(set(xa,y,za),set(xa,y,zb),set(xb,y,zb),set(xb,y,za));
    int poly=addprim(0,"poly");
    foreach(vector pos;p)
    {
        int pt=addpoint(0,worldpos(pos,center,angle));addvertex(0,poly,pt);
        setpointattrib(0,"extrude_direction",pt,set(0.,-1.,0.),"set");
    }
    setprimattrib(0,"extrude_distance",poly,depth,"set");
    setprimattrib(0,"name",poly,part,"set");
    setprimattrib(0,"material_family",poly,"wood","set");
    setprimattrib(0,"Cd",poly,set(.27,.19,.12),"set");
    setprimattrib(0,"role",poly,role,"set");
    setprimattrib(0,"role_id",poly,rid,"set");
    setprimattrib(0,"floor_i",poly,level,"set");
    setprimattrib(0,"component",poly,"interior","set");
}

void plankrect(float xa;float xb;float za;float zb;float y;float depth;
               vector center;float angle;string prefix;string role;int rid;int level)
{
    if(xb-xa<.005 || zb-za<.005) return;
    int count=max(1,int(ceil((xb-xa)/.28)));
    for(int i=0;i<count;i++)
    {
        float a=lerp(xa,xb,float(i)/count),b=lerp(xa,xb,float(i+1)/count);
        rectprofile(a+.0015,b-.0015,za,zb,y,depth,center,angle,
                    prefix+"_board_"+itoa(i),role,rid,level);
    }
}

void member(vector position;vector size;vector center;float angle;
            string part;string material;vector color;string role;int rid;int level)
{
    if(min(size)<.001) return;
    float a=radians(angle);vector x=set(cos(a),0.,-sin(a)),z=set(sin(a),0.,cos(a));
    int pt=addpoint(0,worldpos(position,center,angle));
    matrix3 transform=set(x*size.x,set(0.,size.y,0.),z*size.z);
    setpointattrib(0,"transform",pt,transform,"set");
    setpointattrib(0,"part_name",pt,part,"set");
    setpointattrib(0,"part_material",pt,material,"set");
    setpointattrib(0,"part_color",pt,color,"set");
    setpointattrib(0,"role",pt,role,"set");setpointattrib(0,"role_id",pt,rid,"set");
    setpointattrib(0,"floor_i",pt,level,"set");
}

void beam(vector start;vector end;float width;float depth;vector center;float angle;
          string part;string role;int rid;int level)
{
    vector a=worldpos(start,center,angle),b=worldpos(end,center,angle);
    vector along=normalize(b-a),ref=abs(along.y)<.95?set(0.,1.,0.):set(1.,0.,0.);
    vector x=normalize(cross(along,ref)),z=cross(x,along);
    matrix3 transform=set(x*width,along*distance(a,b),z*depth);
    int pt=addpoint(0,(a+b)*.5);
