function vector[] arch_outline(float width; float height; float rise; float z)
{
    vector p[];
    float spring = height*.5-rise;
    append(p,set(-width*.5,-height*.5,z));
    append(p,set(width*.5,-height*.5,z));
    for (int i=0;i<=12;i++)
    {
        float a = M_PI*float(i)/12.;
        append(p,set(width*.5*cos(a),spring+rise*sin(a),z));
    }
    return p;
}

